const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',image:'M3 3h18v18H3z M3 16l6-6 5 5 3-3 4 4 M15 7h.01',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M2 12h20 M12 2c6 5 6 15 0 20-6-5-6-15 0-20',check:'M5 12l4 4L19 6',alert:'M12 8v5 M12 17h.01 M12 3L2 21h20z',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'M6 6l12 12 M6 18L18 6',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 13h8 M8 17h6',layers:'M12 2L2 7l10 5 10-5z M2 12l10 5 10-5 M2 17l10 5 10-5',monitor:'M2 3h20v14H2z M12 17v5 M7 22h10',chevron:'M9 5l7 7-7 7'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.image}"/></svg>`;
const labels={pass:'Passed',broken:'Broken image',alt:'Alt text issue',unverified:'Unverified',review:'Needs review',performance:'Optimization'};
const colors={pass:'#43856d',broken:'#c4626c',alt:'#d3a04f',unverified:'#6a7584',review:'#8b7bcb',performance:'#91a0b6'};
let saved=[];try{saved=JSON.parse(localStorage.getItem('imagelens-audits-v1')||'[]').filter(a=>a.sampleData===false&&Array.isArray(a.assets));}catch{}
let audit=saved[0]||null,tab='overview',view='home',inventoryView='gallery',viewportFilter='',filter='issues',query='',pageFilter='',typeFilter='',pageNum=1,setup={},activeJob=null,storageWarning='';
const api=async(path,data,method=data?'POST':'GET')=>{let res=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','X-ImageLens':'1'},...(data?{body:JSON.stringify(data)}:{})});let value=await res.json();if(!res.ok)throw Error(value.error||'Request failed.');return value};
const pageLabel=url=>{try{let u=new URL(url);return u.pathname+u.search+u.hash}catch{return url}};
const totals=()=>Object.fromEntries(Object.keys(labels).map(k=>[k,audit.assets.filter(a=>a.status===k).length]));
const hasStatus=(a,k)=>k==='all'||k==='issues'&&a.issues.length>0||k==='pass'&&!a.issues.length||a.issues.some(x=>x.severity===k);
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
function render(){$('#app').innerHTML=`<header class="app-header"><div class="header-inner"><button class="brand image-brand" data-action="home" aria-label="ImageLens home"><img src="brand/imagelens-mark.svg" alt="" width="38" height="38"><span>Image<span class="brand-lens">Lens</span></span></button><nav class="nav" aria-label="Main navigation"><button data-action="home" class="${view==='home'?'active':''}" ${view==='home'?'aria-current="page"':''}>${icon('globe')} Home</button><button data-action="audit" class="${view==='audit'?'active':''}" ${view==='audit'?'aria-current="page"':''}>${icon('grid')} Audit overview</button><button data-action="history" class="${view==='history'?'active':''}" ${view==='history'?'aria-current="page"':''}>${icon('clock')} Scan history</button></nav><div class="header-tools"><label class="theme-control"><span class="sr-only">Appearance</span><select id="theme-select"><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></label><button class="primary btn-icon header-new" data-action="new">${icon('plus')} New audit</button></div></div></header><div class="shell"><div class="workspace-context" role="region" aria-label="Workspace context"><span class="eyebrow">LENS / IMAGE QUALITY</span><span class="local-note">${icon('lock')} Local inspection. Clear evidence.</span></div><main class="main" id="main" tabindex="-1">${view==='history'?historyHTML():view==='home'?emptyHTML():audit?auditHTML():emptyHTML()}</main><footer class="app-footer"><span><strong>LENS</strong> A clearer view of the web.</span><span>ImageLens · Image integrity & accessibility</span></footer></div>`;bindMain();}
function emptyHTML(){return `<section class="hero image-hero"><div class="hero-copy"><div class="eyebrow hero-eyebrow">THE IMAGE AUDIT WORKSPACE</div><h1>Every image.<br>A clearer picture.</h1><p class="hero-intro">Find what breaks. Understand what’s missing. See the evidence behind every image.</p><form id="home-audit-form" class="url-launch"><label for="home-url">Where should we look?</label><div class="url-entry"><span>${icon('globe')}</span><input id="home-url" type="url" placeholder="https://your-website.com" required aria-describedby="home-url-help"><button class="primary btn-icon" type="submit">Start audit ${icon('arrow')}</button></div><p id="home-url-help" class="small">One page, selected sections, or every discovered page.</p><p id="home-url-error" class="error" role="alert"></p></form><div class="start-features"><span>${icon('monitor')} Desktop & mobile</span><span>${icon('lock')} Signed-in sites</span><span>${icon('file')} Shareable evidence</span></div></div><aside class="image-method" aria-label="How ImageLens works"><div class="method-art" aria-hidden="true"><div class="frame-corner c1"></div><div class="frame-corner c2"></div><div class="frame-corner c3"></div><div class="frame-corner c4"></div><img src="brand/imagelens-mark.svg" alt="" width="138" height="138"><div class="art-caption">A CLOSER LOOK AT EVERY ASSET</div></div><div class="method-steps">${[['01','Discover','Bring every selected page into view.'],['02','Inspect','Check resources, variants, and alternatives.'],['03','Resolve','Go from visual evidence to a clear next step.']].map(([n,t,d])=>`<div><span>${n}</span><section><h2>${t}</h2><p>${d}</p></section></div>`).join('')}</div></aside></section><section class="home-workspace"><div class="section-heading"><div><div class="eyebrow">YOUR WORK</div><h2>${saved.length?'Pick up where you left off.':'Thorough inspection. Useful answers.'}</h2></div>${saved.length?'<button class="text-btn" data-action="history">All scan history →</button>':''}</div>${saved.length?`<div class="recent-audits">${saved.slice(0,3).map((a,i)=>`<button class="recent-audit" data-history="${i}"><span class="recent-icon">${icon('image')}</span><span class="recent-site"><strong>${esc(new URL(a.url).hostname)}</strong><small>${a.pages.length} pages · ${a.assets.length} image observations · ${esc(a.scope)}</small></span><span class="recent-date">${new Date(a.date).toLocaleDateString()}</span>${icon('arrow')}</button>`).join('')}</div>`:`<div class="principles"><article><span class="principle-number">01</span><div><h3>Every occurrence matters.</h3><p>A shared resource can have a different purpose on each page. Inspect each occurrence with its surrounding evidence.</p></div></article><article><span class="principle-number">02</span><div><h3>Coverage you can account for.</h3><p>Keep resource failures, text alternatives, and unverified states distinct. Export the findings that matter.</p></div></article></div>`}</section>`}
function auditHTML(){const t=totals(),broken=audit.assets.filter(a=>hasStatus(a,'broken')).length,alt=audit.assets.filter(a=>hasStatus(a,'alt')).length,review=audit.assets.filter(a=>hasStatus(a,'review')).length;return `<div class="heading"><div><span class="eyebrow">IMAGE AUDIT / OVERVIEW</span><h1>Your images, in focus.</h1><p>A clear picture of what works, what breaks, and what needs attention.</p></div><div class="actions"><button class="btn-icon" data-action="export">${icon('download')} Export report</button><button class="primary btn-icon" data-action="new">${icon('plus')} New audit</button></div></div>${storageWarning?`<div class="coverage-note" role="alert">${icon('alert')}<span><strong>Report not saved.</strong> ${esc(storageWarning)} Export it before closing this tab.</span></div>`:''}<section class="site-strip" aria-label="Audit scope"><span class="site-icon">${icon('globe')}</span><div class="site-info"><strong>${esc(new URL(audit.url).hostname)}</strong><div class="small">${esc(audit.scope)} · ${audit.pages.length} pages · Desktop & mobile · ${audit.access==='public'?'Public access':'Signed-in session'} · ${new Date(audit.date).toLocaleString()}</div></div><span class="badge ${audit.unverified?'review':'pass'}">${icon('check')} Audit finished</span></section><div class="coverage-note">${icon('info')}<span><strong>Coverage is part of the result.</strong> ${audit.assets.length} image observations across ${audit.pages.length} selected pages and two viewports. ${audit.coverage.gaps.length} coverage notes. ${esc(audit.coverage.note)}</span></div><section class="metrics" aria-label="Audit summary">${metric('Image observations',audit.assets.length,`${audit.coverage.uniqueResources} unique resources · each viewport retained`,'image')}${metric('Broken images',broken,'Occurrences with a resource failure','alert','var(--red)')}${metric('Alt text issues',alt,'Occurrences with text alternative issues','layers','var(--amber)')}${metric('Needs human review',review,'Context and image purpose','search','var(--accent)')}</section><div class="tabs" role="tablist" aria-label="Report sections">${[['overview','Overview'],['findings','All images'],['coverage','Page coverage']].map(([id,l])=>`<button role="tab" id="tab-${id}" aria-controls="report-content" aria-selected="${tab===id}" tabindex="${tab===id?'0':'-1'}" class="${tab===id?'active':''}" data-tab="${id}">${l}${id==='findings'?`<span class="count">${audit.assets.length}</span>`:''}</button>`).join('')}</div><div id="report-content" role="tabpanel" aria-labelledby="tab-${tab}">${tab==='overview'?chartsHTML(t)+findingsHTML():tab==='findings'?findingsHTML():coverageHTML()}</div><p class="footer-note">ImageLens · ${Math.round(audit.durationMs/1000)} seconds · Automated checks and contextual review are reported separately.</p>`}
function metric(label,num,sub,ic,color='var(--ink)'){return `<div class="metric"><div class="metric-top">${label}${icon(ic)}</div><strong style="color:${color}">${num}</strong><span class="small">${sub}</span></div>`}
function chartsHTML(t){let start=0,denom=audit.assets.length||1;const grad=Object.keys(labels).map(k=>{let end=start+t[k]/denom*100;let stop=`${colors[k]} ${start}% ${end}%`;start=end;return stop}).join(',');let affected=audit.pages.map(p=>({p,n:audit.assets.filter(a=>a.page===p&&a.issues.length).length})).sort((a,b)=>b.n-a.n).slice(0,5);return `<div class="charts"><section class="panel"><div class="panel-head"><div><h2>Image health</h2><p>Primary outcome per image observation</p></div>${icon('image')}</div><div class="health-content"><div class="donut" style="background:${audit.assets.length?`conic-gradient(${grad})`:'#ececf2'}" role="img" aria-label="${t.pass} of ${audit.assets.length} image observations passed automated checks"><div class="donut-hole"><strong>${audit.assets.length?Math.round(t.pass/denom*100):'—'}${audit.assets.length?'<span style="font-size:17px">%</span>':''}</strong><span class="small">checks passed</span></div></div><div class="legend">${Object.keys(labels).map(k=>`<button data-filter="${k}"><span class="dot" style="--color:${colors[k]}"></span>${labels[k]}<strong>${t[k]}</strong></button>`).join('')}</div></div><div class="chart-foot">Filters include secondary findings. Passes do not establish accessibility conformance.</div></section><section class="panel"><div class="panel-head"><div><h2>Where to focus first</h2><p>Pages with the most affected observations</p></div><button class="text-btn" data-tab="coverage">View pages ${icon('arrow')}</button></div>${affected.map(x=>`<div class="bar-row"><button data-page="${esc(x.p)}" title="${esc(x.p)}">${esc(pageLabel(x.p)==='/'?'Homepage':pageLabel(x.p).split('/').pop()||'/')}</button><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="width:${x.n/Math.max(...affected.map(a=>a.n),1)*100}%"></div></div><strong>${x.n}</strong></div>`).join('')}<div class="chart-foot">Select a page to inspect its findings. Multiple issues may affect one image.</div></section></div>`}
function filtered(){return audit.assets.filter(a=>(!viewportFilter||a.viewport===viewportFilter)&&hasStatus(a,filter)&&(!pageFilter||a.page===pageFilter)&&(!typeFilter||a.issues.some(i=>i.code===typeFilter))&&(`${a.name} ${a.page} ${a.issues.map(i=>i.message).join(' ')}`.toLowerCase().includes(query.toLowerCase())))}
function issueTypes(){return [...new Map(audit.assets.flatMap(a=>a.issues.map(i=>[i.code,i]))).values()]}
function findingsHTML(){return `<section class="panel findings"><div class="panel-head"><div><h2>${tab==='overview'?'Findings that deserve a closer look':'Image inventory'}</h2><p>Every occurrence, with the evidence to take action.</p></div><div class="view-switch" role="group" aria-label="Inventory layout"><button data-layout="gallery" aria-pressed="${inventoryView==='gallery'}" aria-label="Gallery view">${icon('grid')}</button><button data-layout="list" aria-pressed="${inventoryView==='list'}" aria-label="List view">${icon('layers')}</button></div></div><div class="table-tools"><label class="search">${icon('search')}<input id="finding-search" aria-label="Search images or pages" placeholder="Search images or findings…" value="${esc(query)}"></label><select id="status-filter" aria-label="Filter by severity">${[['issues','All findings'],['all','All images'],...Object.entries(labels)].map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select><select id="type-filter" aria-label="Filter by issue type"><option value="">Every issue type</option>${issueTypes().map(i=>`<option value="${esc(i.code)}" ${typeFilter===i.code?'selected':''}>${esc(i.code.replaceAll('-',' '))}</option>`).join('')}</select><select id="viewport-filter" aria-label="Filter by viewport"><option value="">Both viewports</option>${[...new Set(audit.assets.map(a=>a.viewport))].map(v=>`<option ${viewportFilter===v?'selected':''}>${esc(v)}</option>`).join('')}</select><select id="page-filter" aria-label="Filter by page"><option value="">All pages</option>${audit.pages.map(p=>`<option ${pageFilter===p?'selected':''} value="${esc(p)}">${esc(pageLabel(p))}</option>`).join('')}</select></div><div id="rows">${rowsHTML()}</div></section>`}
function safePreview(a){return typeof a.preview==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(a.preview)?a.preview:''}
function previewHTML(a,large=false){const preview=safePreview(a);return `<div class="${large?'inspector-preview':'asset-preview'}">${preview?`<img src="${preview}" alt="Captured preview of ${esc(a.name)}" loading="lazy">`:`<div class="preview-fallback">${icon(a.status==='broken'?'alert':'image')}<strong>${a.status==='broken'?'Resource unavailable':a.type==='Inline SVG'?'Inline graphic':'Preview not captured'}</strong><span>${a.status==='broken'?'Inspect the loading evidence':'Full validation evidence is available'}</span></div>`}${large?`<div class="preview-caption">${esc(a.type)} · ${a.naturalWidth||'—'} × ${a.naturalHeight||'—'}<br><span>Preview captured in the scan session. No external images load here.</span></div>`:''}</div>`}
function galleryHTML(){const rows=filtered(),max=Math.max(1,Math.ceil(rows.length/8));pageNum=Math.min(pageNum,max);return `<div class="asset-gallery">${rows.slice((pageNum-1)*8,pageNum*8).map(a=>`<article class="asset-card">${previewHTML(a)}<div class="asset-body"><div class="asset-top"><span class="badge ${a.status}">${labels[a.status]}</span><span class="small">${a.viewport}</span></div><h3 title="${esc(a.name)}">${esc(a.name)}</h3><div class="asset-route" title="${esc(a.page)}">${esc(pageLabel(a.page))}</div><div class="asset-facts"><span>${a.type}</span><span>${a.naturalWidth||'—'} × ${a.naturalHeight||'—'}</span></div><button class="asset-inspect" data-detail="${a.id}" aria-label="Inspect ${esc(a.name)} on ${esc(a.page)}">Inspect evidence ${a.issues.length>1?`<span class="small">${a.issues.length} findings</span>`:''}${icon('arrow')}</button></div></article>`).join('')}</div>${!rows.length?'<div class="empty"><h3>No images match these filters.</h3><p>Try a different issue type, page, or viewport.</p><button class="text-btn" data-action="clear">Clear filters</button></div>':''}<div class="table-footer"><span>${rows.length?`${(pageNum-1)*8+1}–${Math.min(pageNum*8,rows.length)}`:'0'} of ${rows.length} observations</span><div class="inline"><button class="row-action" data-paginate="-1" ${pageNum===1?'disabled':''}>Previous</button><span>${pageNum} / ${max}</span><button class="row-action" data-paginate="1" ${pageNum===max?'disabled':''}>Next</button></div></div>`}
function rowsHTML(){if(inventoryView==='gallery')return galleryHTML();let rows=filtered(),max=Math.max(1,Math.ceil(rows.length/8));pageNum=Math.min(pageNum,max);return `<div class="table-wrap"><table><thead><tr><th scope="col">Image / asset</th><th scope="col">Findings</th><th scope="col">Page</th><th scope="col">Viewport</th><th scope="col">Evidence</th></tr></thead><tbody>${rows.slice((pageNum-1)*8,pageNum*8).map(a=>`<tr><td><div class="asset-cell"><span class="thumb">${icon(a.status==='broken'?'alert':'image')}</span><div><div class="asset-name" title="${esc(a.name)}">${esc(a.name.length>38?a.name.slice(0,35)+'…':a.name)}</div><div class="asset-meta">${a.type} · ${a.bytes?Math.max(1,Math.round(a.bytes/1000))+' KB':'Size unavailable'}</div></div></div></td><td><span class="badge ${a.status}">${labels[a.status]}</span>${a.issues.length>1?`<span class="small"> +${a.issues.length-1}</span>`:''}</td><td title="${esc(a.page)}">${esc(pageLabel(a.page).slice(0,38))}</td><td class="small">${a.viewport}</td><td><button class="row-action" data-detail="${a.id}" aria-label="Inspect ${esc(a.name)} on ${esc(a.page)}">Inspect ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No image observations match these filters.<br><button class="text-btn" data-action="clear">Clear filters</button></div>':''}</div><div class="table-footer"><span>${rows.length?`${(pageNum-1)*8+1}–${Math.min(pageNum*8,rows.length)}`:'0'} of ${rows.length} observations</span><div class="inline"><button class="row-action" data-paginate="-1" ${pageNum===1?'disabled':''}>Previous</button><span>${pageNum} / ${max}</span><button class="row-action" data-paginate="1" ${pageNum===max?'disabled':''}>Next</button></div></div>`}
function coverageHTML(){return `<section class="panel findings"><div class="panel-head"><div><h2>Page coverage</h2><p>Counts include overlapping findings and both viewports. Select a count to inspect.</p></div><span class="badge review">Bounded exploration</span></div><div class="table-wrap"><table class="matrix"><thead><tr><th>Page</th>${Object.values(labels).map(l=>`<th>${l}</th>`).join('')}<th>Viewports checked</th></tr></thead><tbody>${audit.pages.map(p=>`<tr><td>${esc(pageLabel(p))}</td>${Object.keys(labels).map(k=>{let n=audit.assets.filter(a=>a.page===p&&hasStatus(a,k)).length;return `<td><button class="heat ${k!=='pass'&&n?'issue':''}" data-cell="${esc(p)}" data-status="${k}" aria-label="${labels[k]} on ${esc(p)}: ${n}">${n}</button></td>`}).join('')}<td>${audit.pageResults.filter(x=>x.url===p&&x.status==='checked').length} / 2</td></tr>`).join('')}</tbody></table></div></section><section class="panel section-space"><h2>Coverage notes and unverified content</h2><p class="small">A completed scan does not prove that all possible application states were reached.</p>${audit.coverage.gaps.map(g=>`<details class="gap"><summary>${esc(g.reason)} <span class="small">${esc(pageLabel(g.page))}</span></summary><p class="small">${esc(g.detail||g.page)}</p></details>`).join('')||'<p>No traversal errors were recorded. Closed shadow roots, canvas semantics and undiscovered interaction paths still require contextual review.</p>'}</section>`}
function bindMain(){const theme=$('#theme-select');if(theme){theme.value=window.lensTheme?.preference||'system';theme.onchange=()=>window.lensTheme?.set(theme.value)}$('#home-audit-form')?.addEventListener('submit',e=>{e.preventDefault();const raw=$('#home-url').value.trim();try{const u=new URL(raw);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw 0;openSetup(u.href)}catch{$('#home-url-error').textContent='Enter an HTTP or HTTPS address without embedded credentials.'}});document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{inventoryView=b.dataset.layout;pageNum=1;render()});$('#viewport-filter')?.addEventListener('change',e=>{viewportFilter=e.target.value;pageNum=1;refreshRows()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{let a=b.dataset.action;if(a==='home'){view='home';render()}if(a==='new')openSetup();if(a==='export')openExport();if(a==='history'){view='history';render()}if(a==='audit'){view='audit';render()}if(a==='clear'){filter='all';query='';pageFilter='';typeFilter='';viewportFilter='';pageNum=1;render()}});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;pageNum=1;if(tab==='findings'){filter='all';inventoryView='list';}render();$(`#tab-${tab}`)?.focus({preventScroll:true})});document.querySelectorAll('[role=tab]').forEach((b,i)=>b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;document.querySelectorAll('[role=tab]')[n].click()}});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;typeFilter='';tab='findings';pageNum=1;render()});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{pageFilter=b.dataset.page;filter='issues';typeFilter='';tab='findings';pageNum=1;render()});document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{pageFilter=b.dataset.cell;filter=b.dataset.status;typeFilter='';tab='findings';pageNum=1;render()});if($('#finding-search')){$('#finding-search').oninput=e=>{query=e.target.value;pageNum=1;refreshRows()};$('#status-filter').onchange=e=>{filter=e.target.value;pageNum=1;refreshRows()};$('#type-filter').onchange=e=>{typeFilter=e.target.value;pageNum=1;refreshRows()};$('#page-filter').onchange=e=>{pageFilter=e.target.value;pageNum=1;refreshRows()}}bindRows();document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{audit=saved[+b.dataset.history];view='audit';tab='overview';inventoryView='gallery';viewportFilter='';filter='issues';query='';pageFilter='';typeFilter='';render()});}
function refreshRows(){$('#rows').innerHTML=rowsHTML();bindRows()}
function bindRows(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));document.querySelectorAll('[data-paginate]').forEach(b=>b.onclick=()=>{pageNum+=+b.dataset.paginate;refreshRows()});document.querySelector('[data-action="clear"]')?.addEventListener('click',()=>{filter='all';query='';pageFilter='';typeFilter='';viewportFilter='';render()})}
function modal(title,body,foot=''){const d=$('#dialog');d.className=title==='Image evidence'?'inspector-dialog':'';d.innerHTML=`<header class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close" aria-label="Close dialog">${icon('close')}</button></header><div class="dialog-body">${body}</div>${foot?`<footer class="dialog-foot">${foot}</footer>`:''}`;if(!d.open)d.showModal();d.querySelector('.close').onclick=()=>d.close();}
function openDetail(id){const a=audit.assets.find(x=>x.id===id);modal('Image evidence',`${previewHTML(a,true)}<span class="badge ${a.status}">${labels[a.status]}</span><h3 class="section-space">${esc(a.name)}</h3><dl><dt>Page</dt><dd>${esc(a.page)}</dd><dt>Resource</dt><dd>${esc(a.source||'Inline graphic')}</dd><dt>HTTP / decoded</dt><dd>${a.httpStatus||'Status unavailable'} / ${a.loaded?'Yes':'No'}</dd><dt>Viewport / state</dt><dd>${esc(a.viewport)} · ${esc(a.state)}</dd><dt>Selector</dt><dd>${esc(a.selector)}</dd><dt>Alt attribute</dt><dd>${a.alt===null?'Missing':a.alt===''?'Empty (decorative)':esc(a.alt)}</dd><dt>Accessible name</dt><dd>${esc(a.accessibleName||a.parentName||'None recorded')}</dd><dt>Tooltip / description</dt><dd>${esc(a.tooltip||'None present (not inherently a failure)')}</dd><dt>Dimensions</dt><dd>${Math.round(a.width)} × ${Math.round(a.height)} rendered · ${a.naturalWidth} × ${a.naturalHeight} intrinsic</dd></dl><h3>Validation findings</h3>${a.issues.map(i=>`<section class="finding-detail"><span class="badge ${i.severity}">${labels[i.severity]}</span><p><strong>${esc(i.message)}</strong></p><p class="small">${esc(i.fix)}</p></section>`).join('')||'<p>No automatic failure was detected. The meaning of text alternatives still requires contextual review.</p>'}${a.variantResults?.length?`<details class="gap"><summary>${a.variantResults.length} additional responsive candidates</summary>${a.variantResults.map(v=>`<p class="small">${v.loaded?'Decoded':v.timedOut?'Unverified':'Failed'} · ${esc(v.url)}</p>`).join('')}</details>`:''}<h3 class="section-space">Recorded markup</h3><pre>${esc(a.html)}</pre>`,`<span class="small">Actual browser observation</span><button id="related" class="primary">View related occurrences</button>`);$('#related').onclick=()=>{$('#dialog').close();query=a.name;filter='all';pageFilter='';typeFilter='';viewportFilter='';tab='findings';pageNum=1;render()}}
function openSetup(url=''){setup={url,access:'public',sessionId:null,signed:false,scope:'all',selected:new Set(),paths:[],search:'',step:1,gaps:[]};setupUI()}
function selectedPages(){return setup.scope==='current'?[setup.url]:setup.scope==='all'?setup.paths:[...setup.selected]}
function steps(){return `<div class="steps">${['Website & access','Choose pages','Review & run'].map((t,i)=>`<span class="${setup.step===i+1?'active':''}">${i+1}. ${t}</span>`).join('')}</div>`}
function setupUI(){let body=steps();if(setup.step===1){body+=`<div class="field"><label for="site-url">Website or current page URL</label><input id="site-url" type="url" value="${esc(setup.url)}" placeholder="https://your-website.com"><span class="small">Paste a specific page URL for a current-page audit.</span><span id="url-error" class="error" role="alert"></span></div><h3>Access method</h3><div class="choice-grid" style="grid-template-columns:1fr 1fr">${[['public','Public website','Pages available without signing in.'],['private','Requires sign-in','Keep a real authenticated browser session.']].map(([v,l,s])=>`<label class="choice ${setup.access===v?'selected':''}"><input type="radio" name="access" value="${v}" ${setup.access===v?'checked':''}><span><strong>${l}</strong><small>${s}</small></span></label>`).join('')}</div>${setup.access==='private'?`<div class="coverage-note">${icon('lock')}<span>Sign in directly in the browser window. Return here and confirm when the application is ready. Credentials are not entered into ImageLens.</span></div><button id="sign-in" class="btn-icon">${icon(setup.signed?'check':'lock')}${setup.signed?'Session connected':setup.sessionId?'Confirm completed sign-in':'Open sign-in browser'}</button>`:''}<p class="small section-space">The scanner visits pages and supported disclosure controls. Use an appropriate account for authenticated environments; automatic exploration avoids forms and known action requests.</p>`}else if(setup.step===2){body+=`<h3>Choose your audit scope</h3><p class="small">Every selected page receives the same image validation checks.</p><div class="choice-grid">${[['current','Current page','Only the URL you entered.'],['all','All pages','Every discovered page.'],['selected','Select pages','Choose pages or whole sections.']].map(([v,l,s])=>`<label class="choice ${setup.scope===v?'selected':''}"><input type="radio" name="scope" value="${v}" ${setup.scope===v?'checked':''}><span><strong>${l}</strong><small>${s}</small></span></label>`).join('')}</div>${setup.scope==='current'?`<div class="page-list"><div class="page-item">${icon('file')}<span>${esc(setup.url)}</span></div></div>`:`<div class="inline between"><span class="small">${setup.paths.length} pages discovered</span>${setup.scope==='selected'?'<div><button id="select-all" class="text-btn">Select all</button><button id="select-none" class="text-btn">Clear</button></div>':''}</div>${setup.paths.length?'':`<button id="discover" class="btn-icon">${icon('search')} Discover website pages</button><p class="small">Follows same-site links, up to 200 pages. Discovery limits and failures are reported.</p>`}${setup.scope==='selected'?`<input id="page-search" style="width:100%" placeholder="Search pages or sections…" aria-label="Search discovered pages" value="${esc(setup.search)}"><div class="inline" style="flex-wrap:wrap;margin-top:8px">${[...new Set(setup.paths.map(p=>'/'+new URL(p).pathname.split('/')[1]).filter(p=>p!=='/'))].slice(0,8).map(p=>`<button class="text-btn" data-section="${esc(p)}">Select ${esc(p)}</button>`).join('')}</div>`:''}<div class="page-list" id="select-pages">${pageChoices()}</div>${setup.scope==='selected'?`<details><summary class="small" style="cursor:pointer">Add specific page URLs</summary><div class="field section-space"><label for="manual-pages">Same-site URLs or paths, one per line</label><textarea id="manual-pages" rows="3" placeholder="/contact&#10;/products"></textarea><span id="manual-error" class="error" role="alert"></span><button id="add-pages">Add pages</button></div></details>`:''}`}<div class="small" id="selection-count">${selectedPages().length} pages selected</div>${setup.gaps.length?`<p class="small">${setup.gaps.length} discovery notes will be included in the audit report.</p>`:''}`}else{body+=`<h3>Ready to look closer.</h3><p>${selectedPages().length} pages on <strong>${esc(new URL(setup.url).hostname)}</strong></p><div class="check-grid">${['Desktop & mobile','Responsive image candidates','Lazy-loaded images','CSS backgrounds & SVGs','Alt text & accessible names','Tooltips checked separately','Image load & decode','Supported disclosures & tabs'].map(t=>`<div class="check-item">${icon('check')}${t}</div>`).join('')}</div><div class="coverage-note">${icon('info')}<span>Closed shadow roots, unrecognized interactions, and exhaustive carousel journeys cannot be guaranteed. Timeouts and traversal limits are recorded explicitly.</span></div>`}modal('New image audit',body,`<button id="back">${setup.step===1?'Cancel':'Back'}</button><button id="next" class="primary btn-icon">${setup.step===3?'Run image audit':setup.step===1?'Choose pages':'Review audit'} ${icon('arrow')}</button>`);$('#back').onclick=()=>{if(setup.step===1)$('#dialog').close();else{setup.step--;setupUI()}};$('#next').onclick=async()=>{if(setup.step===1){const old=setup.url;setup.url=$('#site-url').value.trim();try{const u=new URL(setup.url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw 0;setup.url=u.href}catch{$('#url-error').textContent='Enter a valid HTTP or HTTPS URL without embedded credentials.';return}if(setup.sessionId&&new URL(old).origin!==new URL(setup.url).origin){setup.signed=false;setup.sessionId=null;}if(old!==setup.url){setup.paths=[];setup.selected=new Set();setup.gaps=[];}if(setup.access==='private'&&!setup.signed){$('#url-error').textContent='Complete browser sign-in before continuing.';return}}if(setup.step===2&&(!selectedPages().length||selectedPages().length>200)){toast('Select between 1 and 200 pages.');return}if(setup.step===3){runAudit();return}setup.step++;setupUI()};document.querySelectorAll('[name=access]').forEach(x=>x.onchange=()=>{setup.url=$('#site-url').value;setup.access=x.value;setupUI()});$('#sign-in')?.addEventListener('click',async e=>{const b=e.currentTarget;b.disabled=true;try{if(!setup.sessionId){setup.url=$('#site-url').value.trim();const result=await api('sessions',{url:setup.url});setup.sessionId=result.id;toast('Sign in in the browser, then return to confirm.')}else{const connected=await api(`sessions/${setup.sessionId}/confirm`,{});setup.url=connected.url;setup.signed=true;}setupUI()}catch(e){$('#url-error').textContent=e.message;b.disabled=false}});document.querySelectorAll('[name=scope]').forEach(x=>x.onchange=()=>{setup.scope=x.value;setupUI()});$('#discover')?.addEventListener('click',()=>runDiscovery());$('#page-search')?.addEventListener('input',e=>{setup.search=e.target.value;$('#select-pages').innerHTML=pageChoices();bindPageChoices()});$('#select-all')?.addEventListener('click',()=>{setup.paths.forEach(p=>setup.selected.add(p));setupUI()});$('#select-none')?.addEventListener('click',()=>{setup.selected.clear();setupUI()});document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{setup.paths.filter(p=>{let path=new URL(p).pathname;return path===b.dataset.section||path.startsWith(b.dataset.section+'/')}).forEach(p=>setup.selected.add(p));setupUI()});$('#add-pages')?.addEventListener('click',()=>{let entries=$('#manual-pages').value.split('\n').map(x=>x.trim()).filter(Boolean),parsed=[];try{if(!entries.length)throw 0;for(let p of entries){let u=new URL(p,setup.url);if(u.origin!==new URL(setup.url).origin||u.username||u.password)throw 0;parsed.push(u.href)}}catch{$('#manual-error').textContent='Enter paths or URLs from the same website.';return}parsed.forEach(p=>{if(!setup.paths.includes(p))setup.paths.push(p);setup.selected.add(p)});setupUI()});bindPageChoices()}
function pageChoices(){let pages=setup.paths.filter(p=>p.toLowerCase().includes(setup.search.toLowerCase()));return pages.length?pages.map(p=>`<label class="page-item"><input type="checkbox" data-select="${esc(p)}" ${setup.scope==='all'||setup.selected.has(p)?'checked':''} ${setup.scope==='all'?'disabled':''}><span>${esc(pageLabel(p))}</span></label>`).join(''):'<div class="empty">No pages to display.</div>'}
function bindPageChoices(){document.querySelectorAll('[data-select]').forEach(c=>c.onchange=()=>{c.checked?setup.selected.add(c.dataset.select):setup.selected.delete(c.dataset.select);$('#selection-count').textContent=`${selectedPages().length} pages selected`})}
function readHistory(){try{return JSON.parse(localStorage.getItem('imagelens-audits-v1')||'[]').filter(a=>a.sampleData===false&&Array.isArray(a.assets));}catch{return[]}}
function saveAudit(result){audit=result;const records=[audit,...readHistory(),...saved];saved=[...new Map(records.map(a=>[a.id,a])).values()].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,10);storageWarning='';try{localStorage.setItem('imagelens-audits-v1',JSON.stringify(saved))}catch{storageWarning='Browser storage is full or unavailable.'}}
function finishDiscovery(result){setup.paths=result.pages.map(p=>p.url);setup.selected=new Set(setup.paths);setup.gaps=result.gaps;setupUI();toast(`Discovered ${setup.paths.length} pages.`)}
async function finishAudit(result){result.coverage.gaps.unshift(...setup.gaps);result.unverified=result.coverage.gaps.length;if(navigator.locks){await navigator.locks.request('imagelens-history',()=>saveAudit(result))}else saveAudit(result);$('#dialog').close();view='audit';tab='overview';inventoryView='gallery';viewportFilter='';filter='issues';query='';pageFilter='';typeFilter='';pageNum=1;render();toast(storageWarning?'Audit complete. Export this unsaved report to keep it.':`Audit complete: ${audit.assets.length} image observations.`)}
function rememberJob(kind,input){try{sessionStorage.setItem('imagelens-active-job',JSON.stringify({kind,input,setup:{...setup,selected:[...setup.selected]}}))}catch{toast('Scan progress cannot be restored after a refresh in this browser.')}}
function forgetJob(){try{sessionStorage.removeItem('imagelens-active-job')}catch{}}
async function runJob(kind,resume=null){const input=resume?.input||{kind,url:setup.url,requestId:crypto.randomUUID(),sessionId:setup.access==='private'?setup.sessionId:null,pages:kind==='scan'?selectedPages():undefined,scope:{all:'All discovered pages',current:'Current page',selected:'Selected pages'}[setup.scope]};let token={id:input.requestId,cancelled:false};activeJob=token;rememberJob(kind,input);modal(kind==='discover'?'Discovering website pages':'Inspecting website images',`<h3 id="scan-stage">${resume?'Reconnecting to your audit…':'Starting browser…'}</h3><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-label="Audit progress"><div class="progress-fill" style="width:2%"></div></div><p class="small" id="scan-progress" aria-live="polite">Preparing your ${setup.access==='private'?'signed-in':'public'} browser session.</p><p class="small">You can refresh this tab and reconnect to this audit.</p>`,`<span class="small">Live browser inspection</span><button id="cancel-scan">Cancel</button>`);$('#cancel-scan').onclick=()=>$('#dialog').close();try{const job=await api('jobs',input);token.id=job.id;if(token.cancelled){await api('jobs/'+job.id,null,'DELETE');return}let retries=0;while(!token.cancelled){let data;try{data=await api('jobs/'+job.id);retries=0}catch(e){if(token.cancelled)return;if(++retries>5)throw e;$('#scan-stage').textContent='Connection interrupted. Reconnecting…';await new Promise(r=>setTimeout(r,1000));continue;}if(token.cancelled)return;if(data.status==='error')throw Error(data.error);if(data.status==='cancelled')throw Error('The audit was cancelled.');if(data.status==='complete'){activeJob=null;forgetJob();await(kind==='discover'?finishDiscovery:finishAudit)(data.result);return}let p=data.progress;$('#scan-stage').textContent=p.message;$('#scan-progress').textContent=`${p.done||0} of ${p.total||'…'} ${kind==='scan'?'page / viewport checks':'discovery candidates'} · ${p.images||0} image observations`;$('.progress-fill').style.width=(p.total?Math.max(2,p.done/p.total*100):2)+'%';await new Promise(r=>setTimeout(r,650));}}catch(e){if(token.cancelled)return;activeJob=null;const sessionError=/session|sign.in|browser.*closed/i.test(e.message);if(sessionError){forgetJob();setup.sessionId=null;setup.signed=false;setup.step=1;}else activeJob=token;modal('Unable to complete the audit',`<p class="error">${esc(e.message)}</p><p class="small">Your previous report is unchanged. ${sessionError?'Reconnect your sign-in session; page selections are retained.':'Reconnect to the existing job or return to setup.'}</p>`,`<button id="retry">Back to setup</button>${sessionError?'':'<button id="reconnect" class="primary">Reconnect to audit</button>'}`);$('#retry').onclick=()=>{activeJob=null;api('jobs/'+token.id,null,'DELETE').catch(()=>{});forgetJob();setupUI()};$('#reconnect')?.addEventListener('click',()=>runJob(kind,{input}));}}
function runDiscovery(){runJob('discover')}
function runAudit(){runJob('scan')}
$('#dialog').addEventListener('close',()=>{if(activeJob){forgetJob();activeJob.cancelled=true;if(activeJob.id)api('jobs/'+activeJob.id,null,'DELETE').catch(()=>{});activeJob=null;setup.sessionId=null;setup.signed=false;toast('Audit cancelled. Browser inspection stopped.')}else if(setup.sessionId){api('sessions/'+setup.sessionId,null,'DELETE').catch(()=>{});setup.sessionId=null;setup.signed=false;}});
function historyHTML(){return `<div class="heading"><div><h1>Scan history</h1><p>Your audits, saved in this browser.</p></div><button class="primary btn-icon" data-action="new">${icon('plus')} New audit</button></div>${!saved.length?`<section class="panel empty"><h2>No audits yet.</h2><p>Run an image audit to create your first report.</p></section>`:`<section class="panel findings"><div class="table-wrap"><table><thead><tr><th>Website</th><th>Date</th><th>Scope</th><th>Observations</th><th>Report</th></tr></thead><tbody>${saved.map((a,i)=>`<tr><td>${esc(new URL(a.url).hostname)}</td><td>${new Date(a.date).toLocaleString()}</td><td>${a.pages.length} pages · ${esc(a.scope)}</td><td>${a.assets.length}</td><td><button class="row-action" data-history="${i}">Open report ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div></section>`}`}
function reportRuntime(){const root=document.querySelector('#report-data');const data=JSON.parse(root.textContent),rows=[...document.querySelectorAll('tbody tr')];const q=document.querySelector('#q'),severity=document.querySelector('#severity'),type=document.querySelector('#issue-type'),page=document.querySelector('#report-page'),vp=document.querySelector('#viewport');function apply(){let n=0;rows.forEach((r,i)=>{const a=data.assets[i],show=(!q.value||r.textContent.toLowerCase().includes(q.value.toLowerCase()))&&(!severity.value||(severity.value==='pass'?a.issues.length===0:a.issues.some(f=>f.severity===severity.value)))&&(!type.value||a.issues.some(f=>f.code===type.value))&&(!page.value||a.page===page.value)&&(!vp.value||a.viewport===vp.value);r.hidden=!show;if(show)n++;});document.querySelector('#visible-count').textContent=`${n} of ${rows.length} image observations`;document.querySelector('#no-results').hidden=n!==0;document.querySelectorAll('[data-category]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.category===severity.value);});}for(const el of[q,severity,type,page,vp])el.addEventListener(el===q?'input':'change',apply);document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{severity.value=severity.value===b.dataset.category?'':b.dataset.category;apply()});document.querySelector('#reset').onclick=()=>{for(const el of[q,severity,type,page,vp])el.value='';apply()};document.querySelector('#expand').onclick=()=>rows.filter(r=>!r.hidden).forEach(r=>r.querySelectorAll('details').forEach(d=>d.open=true));document.querySelector('#collapse').onclick=()=>document.querySelectorAll('tbody details').forEach(d=>d.open=false);document.querySelector('#download-filtered').onclick=()=>{const cell=v=>'"'+String(v??'').replace(/^\s*[=+@-]/,"'$&").replaceAll('"','""')+'"';const content=[['resource','page','viewport','issues','alt','selector'].join(','),...data.assets.filter((a,i)=>!rows[i].hidden).map(a=>[a.source,a.page,a.viewport,a.issues.map(i=>i.code).join('; '),a.alt,a.selector].map(cell).join(','))].join('\r\n');const u=URL.createObjectURL(new Blob([content],{type:'text/csv'}));const a=document.createElement('a');a.href=u;a.download='imagelens-filtered.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};document.querySelector('#print').onclick=()=>window.print();apply();}
function reportHTML(){const counts=Object.fromEntries(Object.keys(labels).map(k=>[k,audit.assets.filter(a=>hasStatus(a,k)).length]));const data=JSON.stringify({assets:audit.assets}).replaceAll('<','\\u003c');return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ImageLens · ${esc(new URL(audit.url).hostname)}</title><style>:root{font-family:system-ui,sans-serif;color:#202332;background:#f7f8fb}*{box-sizing:border-box}body{max-width:1250px;margin:0 auto;padding:38px 25px}h1{font-size:32px;letter-spacing:-1px}h2{font-size:20px}p{line-height:1.65;color:#626879}.meta{font-size:13px}.cards{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin:25px 0}.cards button{text-align:left;padding:16px;background:white;min-width:0}.cards strong{display:block;font-size:26px;margin:8px 0}.cards button[aria-pressed=true]{outline:2px solid #126c74;background:#e6f2f3}.bar{height:5px;background:#126c74;margin-top:15px;border-radius:2px}.toolbar{display:flex;gap:10px;flex-wrap:wrap;padding:20px;background:white;border:1px solid #dfe3ec;border-radius:10px;margin:20px 0}.toolbar input{flex:1;min-width:180px}input,select,button{font:inherit;border:1px solid #bdc5d5;border-radius:6px;padding:10px;background:white;color:#202332}button{cursor:pointer}button:hover{background:#e6f2f3}:focus-visible{outline:3px solid #126c74;outline-offset:2px}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:20px 0;font-size:12px}table{border-collapse:collapse;width:100%;font-size:12px;background:white}th,td{padding:14px;border-bottom:1px solid #dfe3ec;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#f0f2f7}td:first-child{width:25%;max-width:300px}small{display:block;color:#626879;margin-top:6px}.badge{display:inline-block;padding:4px 7px;border-radius:4px;background:#f0f2f7;margin:0 4px 4px 0;font-size:11px}.broken,.alt{background:#f9e9e8;color:#96353e}.review,.unverified{background:#e6f2f3;color:#126c74}.pass{background:#e6f2ed;color:#27694f}details{margin:12px 0}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f7f8fb;padding:12px;border-radius:5px;max-width:550px}.coverage{border:1px solid #dfe3ec;border-radius:9px;background:#e6f2f3;padding:16px;margin:20px 0}.finding{padding:10px 0;border-bottom:1px solid #eee}.table-scroll{overflow:auto}#no-results{text-align:center;padding:30px}@media(max-width:700px){.cards{grid-template-columns:repeat(2,1fr)}body{padding:20px 14px}.toolbar select{max-width:100%}.table-scroll table{min-width:750px}}@media print{body{padding:0;background:white;font-size:10px}.toolbar,.controls,button#print{display:none}.cards{grid-template-columns:repeat(3,1fr)}.cards button{border:1px solid #ccc}.table-scroll{overflow:visible}table{font-size:9px}th,td{padding:6px}tr{break-inside:avoid}details{display:block}details>*{display:block!important}details::details-content{content-visibility:visible!important;height:auto!important}pre{max-width:300px}.coverage{break-inside:avoid}}</style></head><body><main><h1>ImageLens</h1><h2>Image quality audit</h2><p class="meta">${esc(audit.url)}<br>${new Date(audit.date).toLocaleString()} · ${esc(audit.scope)} · ${audit.pages.length} pages · Desktop & mobile · ${audit.access==='private'?'Authenticated':'Public'} access</p><div class="cards">${Object.entries(counts).map(([k,n])=>`<button data-category="${k}" aria-pressed="false"><span>${labels[k]}</span><strong>${n}</strong><div class="bar" style="width:${n/(audit.assets.length||1)*100}%;background:${colors[k]}"></div></button>`).join('')}</div><p class="meta">${audit.assets.length} observations · ${audit.coverage.uniqueResources} unique resources. Categories overlap when one image has multiple findings. Select a category to filter.</p><section class="coverage"><strong>Coverage and interpretation</strong><p class="meta">${esc(audit.coverage.note)} Automated passes are not a claim of accessibility conformance. ${audit.unverified} coverage notes.</p><details><summary>View coverage notes and limits</summary>${audit.coverage.gaps.map(g=>`<p class="meta"><strong>${esc(g.reason)}</strong> · ${esc(g.page)}<br>${esc(g.detail)}</p>`).join('')||'<p>No traversal errors recorded.</p>'}<pre>${esc(JSON.stringify(audit.coverage.limits,null,2))}</pre></details></section><div class="toolbar"><input id="q" aria-label="Search report" placeholder="Search asset, issue, or evidence…"><select id="severity" aria-label="Filter by category"><option value="">All categories</option>${Object.entries(labels).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select><select id="issue-type" aria-label="Filter by issue type"><option value="">All issue types</option>${issueTypes().map(i=>`<option value="${esc(i.code)}">${esc(i.code.replaceAll('-',' '))}</option>`).join('')}</select><select id="report-page" aria-label="Filter by page"><option value="">All pages</option>${audit.pages.map(p=>`<option value="${esc(p)}">${esc(pageLabel(p))}</option>`).join('')}</select><select id="viewport" aria-label="Filter by viewport"><option value="">Both viewports</option><option>Desktop</option><option>Mobile</option></select><button id="reset">Clear filters</button></div><div class="controls"><strong id="visible-count" role="status"></strong><button id="expand">Expand visible evidence</button><button id="collapse">Collapse evidence</button><button id="download-filtered">Export filtered CSV</button><button id="print">Print filtered report</button></div><div class="table-scroll"><table><thead><tr><th>Image / page</th><th>Findings</th><th>Viewport & evidence</th></tr></thead><tbody>${audit.assets.map(a=>`<tr><td><strong>${esc(a.name)}</strong><small>${esc(a.page)}</small><small>${esc(a.type)}</small></td><td>${a.issues.length?a.issues.map(i=>`<div class="finding"><span class="badge ${i.severity}">${esc(i.code)}</span><div>${esc(i.message)}</div><small>Next step: ${esc(i.fix)}</small></div>`).join(''):'<span class="badge pass">Passed automated checks</span>'}</td><td>${a.viewport} · ${esc(a.state)}<details><summary>Inspect evidence</summary><p>Source: ${esc(a.source||'Inline SVG')}</p><p>Decoded: ${a.loaded?'yes':'no'} · HTTP: ${a.httpStatus||'unavailable'}</p><p>Alt: ${a.alt===null?'missing':a.alt===''?'empty':esc(a.alt)}</p><p>Accessible name: ${esc(a.accessibleName||a.parentName||'none recorded')}</p><p>Tooltip: ${esc(a.tooltip||'none')}</p><p>Selector: ${esc(a.selector)}</p><pre>${esc(a.html)}</pre>${a.variantResults.map(v=>`<p>${v.loaded?'Decoded':'Not decoded'}: ${esc(v.url)}</p>`).join('')}</details></td></tr>`).join('')}</tbody></table></div><p id="no-results" hidden>No observations match these filters.</p><p class="meta">Generated by ImageLens. This report is self-contained and makes no external requests.</p></main><script type="application/json" id="report-data">${data}</script><script>(${reportRuntime.toString()})();</script></body></html>`}
function download(content,ext,mime){let url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=`imagelens-${new URL(audit.url).hostname}-${audit.date.slice(0,10)}.${ext}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast(`${ext.toUpperCase()} report downloaded.`)}
function openExport(){modal('Export your report',`<p style="margin:0 0 20px">Share the full audit with every observation, issue, and coverage note.</p><div class="report-options">${[['html','Interactive HTML','Category charts, issue filters, page and viewport filters, expandable evidence, and filtered CSV export.'],['pdf','PDF report','A downloadable print-ready report with all findings and evidence.'],['csv','CSV spreadsheet','Every occurrence with all issue codes, pages, and selectors.'],['json','JSON evidence','Complete structured results and coverage details.']].map(([v,l,s])=>`<button data-export="${v}">${icon('file')}<span>${l}<small>${s}</small></span>${icon('download')}</button>`).join('')}</div><p id="export-error" class="error" role="alert"></p><p class="small section-space">Full-audit exports ignore dashboard filters. Use the HTML report to share a filtered view.</p>`);document.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>{let type=b.dataset.export;try{if(type==='html')download(reportHTML(),'html','text/html');if(type==='json')download(JSON.stringify(audit,null,2),'json','application/json');if(type==='csv'){let keys=['name','source','page','viewport','status','alt','selector','bytes'];const cell=v=>'"'+String(v??'Missing').replace(/^\s*[=+@-]/,"'$&").replaceAll('"','""')+'"';download([[...keys,'issueCodes','coverageNote'].join(','),...audit.assets.map(a=>[...keys.map(k=>a[k]),a.issues.map(i=>i.code).join('; '),audit.coverage.note].map(cell).join(','))].join('\r\n'),'csv','text/csv')}if(type==='pdf'){b.disabled=true;b.querySelector('small').textContent='Generating PDF…';const res=await fetch('/api/pdf',{method:'POST',headers:{'Content-Type':'application/json','X-ImageLens':'1'},body:JSON.stringify({html:reportHTML()})});if(!res.ok)throw Error((await res.json()).error);download(await res.blob(),'pdf','application/pdf');b.disabled=false;b.querySelector('small').textContent='Download another copy';}}catch(e){$('#export-error').textContent=e.message;b.disabled=false}})}
render();

window.addEventListener('storage',e=>{if(e.key==='imagelens-audits-v1'){saved=readHistory();if(view==='history'&&!$('#dialog').open)render();}});
try{const pending=JSON.parse(sessionStorage.getItem('imagelens-active-job')||'null');if(pending?.input?.requestId){setup={...pending.setup,selected:new Set(pending.setup.selected)};runJob(pending.kind,pending)}}catch{forgetJob()}
